/**
 * Lexend Font Loader for jsPDF
 *
 * Loads Lexend font family for use in PDF generation.
 * Uses Google Fonts API to fetch and load the font.
 */

import jsPDF from 'jspdf'

// Try to import base64 fonts if available
let LEXEND_REGULAR_BASE64 = ''
let LEXEND_BOLD_BASE64 = ''

// Dynamically load fonts if available (lexendFonts.ts is generated by script)
// Using a function to handle the async import
async function loadFontsIfAvailable() {
  try {
    // @ts-expect-error - lexendFonts.ts may not exist (generated by script)
    const lexendFonts = await import('./lexendFonts')
    LEXEND_REGULAR_BASE64 = lexendFonts.LEXEND_REGULAR_BASE64 || ''
    LEXEND_BOLD_BASE64 = lexendFonts.LEXEND_BOLD_BASE64 || ''
  } catch {
    // Fonts not available, will use fallback
  }
}

// Load fonts asynchronously (non-blocking)
loadFontsIfAvailable()

// Cache for loaded fonts
let lexendRegularLoaded = false
let lexendBoldLoaded = false

/**
 * Loads Lexend font from base64 strings
 * This function loads the font if base64 strings are available
 */
export function loadLexendFont(doc: jsPDF): void {
  try {
    // If already loaded, just return
    if (lexendRegularLoaded && lexendBoldLoaded) {
      return
    }

    // Check if font is already in the document
    const fonts = doc.getFontList()
    if ('Lexend' in fonts) {
      lexendRegularLoaded = true
      lexendBoldLoaded = true
      return
    }

    // If we have base64 fonts, load them
    if (LEXEND_REGULAR_BASE64 && LEXEND_BOLD_BASE64) {
      loadLexendFontFromBase64(doc, LEXEND_REGULAR_BASE64, LEXEND_BOLD_BASE64)
    }
  } catch (error) {
    console.warn('Failed to load Lexend font, using fallback:', error)
  }
}

/**
 * Checks if Lexend font is loaded
 */
export function isLexendLoaded(doc: jsPDF): boolean {
  try {
    const fonts = doc.getFontList()
    return 'Lexend' in fonts
  } catch {
    return false
  }
}

/**
 * Load Lexend font from base64 strings
 * Call this with base64 encoded font files
 */
export function loadLexendFontFromBase64(
  doc: jsPDF,
  regularBase64: string,
  boldBase64: string
): void {
  try {
    if (!regularBase64 || !boldBase64) {
      console.warn('Lexend font base64 strings not provided')
      return
    }

    // Add font files to virtual file system
    doc.addFileToVFS('Lexend-Regular.ttf', regularBase64)
    doc.addFileToVFS('Lexend-Bold.ttf', boldBase64)

    // Add fonts
    doc.addFont('Lexend-Regular.ttf', 'Lexend', 'normal')
    doc.addFont('Lexend-Bold.ttf', 'Lexend', 'bold')

    lexendRegularLoaded = true
    lexendBoldLoaded = true
  } catch (error) {
    console.warn('Failed to load Lexend font from base64:', error)
  }
}
